import{_ as n,C as s,o,c,a3 as t,E as a}from"./chunks/framework.bGC-1KKp.js";const f=JSON.parse('{"title":"Lab 01 — Enquête technique : comparer deux sites","description":"","frontmatter":{"title":"Lab 01 — Enquête technique : comparer deux sites","aside":false},"headers":[],"relativePath":"labs/lab01-enquete-technique.md","filePath":"labs/lab01-enquete-technique.md"}'),u={name:"labs/lab01-enquete-technique.md"};function p(d,e,h,b,g,m){const r=s("ParcoursLab"),l=s("BarreNavigateur"),i=s("JaugesPageSpeed");return o(),c("div",null,[e[0]||(e[0]=t('<h1 id="lab-01-—-enquete-technique-comparer-deux-sites" tabindex="-1">Lab 01 — Enquête technique : comparer deux sites <a class="header-anchor" href="#lab-01-—-enquete-technique-comparer-deux-sites" aria-label="Permalink to &quot;Lab 01 — Enquête technique : comparer deux sites&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectifs du laboratoire</strong><br><ul class="list-disc pl-5"><li>Utiliser des outils gratuits pour découvrir comment un site Web est construit.</li><li>Relever les ressources techniques d&#39;un site : plateforme, hébergement, domaine, sécurité, services externes.</li><li>Évaluer la performance et l&#39;affichage mobile d&#39;un site.</li><li>Comparer deux sites et <strong>justifier un jugement</strong> à partir d&#39;observations.</li></ul></div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Modalités</strong><br><ul class="list-disc pl-5"><li>En <strong>duo</strong> (salle de sous-groupe).</li><li>Durée : environ 1 h 30, puis mise en commun en grand groupe.</li><li>Remise : la fiche d&#39;observation remplie, déposée dans l&#39;<strong>équipe Teams du cours</strong>. Ce travail est <strong>formatif</strong> (non noté).</li></ul></div><hr><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>Deux restaurants peuvent offrir le même service, mais avec des sites construits de façons complètement différentes. Votre travail : <strong>enquêter</strong> sur deux sites, comme le ferait un analyste avant de conseiller un client.</p><p>À la fin, vous devrez répondre à une question de jugement :</p><blockquote><p><strong>Lequel de ces deux sites serait le plus facile à faire évoluer ? Pourquoi ?</strong></p></blockquote><p>Il n&#39;y a pas de réponse évidente. Ce qui compte, c&#39;est la qualité de vos <strong>observations</strong> et de votre <strong>justification</strong>.</p><h3 id="le-parcours-de-l-enquete" tabindex="-1">Le parcours de l&#39;enquête <a class="header-anchor" href="#le-parcours-de-l-enquete" aria-label="Permalink to &quot;Le parcours de l&#39;enquête&quot;">​</a></h3>',10)),a(r),e[1]||(e[1]=t('<hr><h2 id="les-paires-de-sites" tabindex="-1">Les paires de sites <a class="header-anchor" href="#les-paires-de-sites" aria-label="Permalink to &quot;Les paires de sites&quot;">​</a></h2><p>L&#39;enseignant attribue une paire à chaque duo.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Paire</th><th style="text-align:left;">Thème</th><th style="text-align:left;">Site A</th><th style="text-align:left;">Site B</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;">Deux poutineries</td><td style="text-align:left;"><a href="https://labanquise.com" target="_blank" rel="noreferrer">La Banquise</a></td><td style="text-align:left;"><a href="https://lecourteau.com" target="_blank" rel="noreferrer">Casse-Croûte Courteau</a></td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;">Deux chaînes</td><td style="text-align:left;"><a href="https://thaiexpress.ca" target="_blank" rel="noreferrer">Thaï Express</a></td><td style="text-align:left;"><a href="https://ashtonrestaurants.ca" target="_blank" rel="noreferrer">Ashton</a></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;">Deux restaurants qui vendent leurs produits</td><td style="text-align:left;"><a href="https://schwartzsdeli.com" target="_blank" rel="noreferrer">Schwartz&#39;s</a></td><td style="text-align:left;"><a href="https://commensal.com" target="_blank" rel="noreferrer">Commensal</a></td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;">Deux tables gastronomiques</td><td style="text-align:left;"><a href="https://joebeef.com" target="_blank" rel="noreferrer">Joe Beef</a></td><td style="text-align:left;"><a href="https://epibuvette.ca" target="_blank" rel="noreferrer">Épi, buvette de quartier</a></td></tr></tbody></table><hr><h2 id="preparation" tabindex="-1">Préparation (10 min) <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Préparation (10 min) {#preparation}&quot;">​</a></h2><h3 id="_1-telecharger-la-fiche" tabindex="-1">1. Télécharger la fiche <a class="header-anchor" href="#_1-telecharger-la-fiche" aria-label="Permalink to &quot;1. Télécharger la fiche&quot;">​</a></h3><p><a href="./../fiches/lab01-fiche-observation.docx" download>Télécharger la fiche d&#39;observation (Word)</a></p><p>Une seule fiche par duo. Travaillez dans un document partagé (OneDrive, Google Docs…) pour la remplir à deux.</p><h3 id="_2-installer-les-outils" tabindex="-1">2. Installer les outils <a class="header-anchor" href="#_2-installer-les-outils" aria-label="Permalink to &quot;2. Installer les outils&quot;">​</a></h3><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Installer l&#39;extension <a href="https://www.wappalyzer.com/apps/" target="_blank">Wappalyzer</a> dans Chrome, Edge ou Firefox, puis l&#39;épingler à la barre d&#39;outils</span></label></li><li><label><input type="checkbox"><span class="check-text">Ouvrir <a href="https://pagespeed.web.dev/" target="_blank">PageSpeed Insights</a> dans un onglet</span></label></li><li><label><input type="checkbox"><span class="check-text">Ouvrir <a href="https://lookup.icann.org/" target="_blank">ICANN Lookup</a> (recherche WHOIS) dans un onglet</span></label></li><li><label><input type="checkbox"><span class="check-text">Vérifier que les outils de développement s&#39;ouvrent avec <kbd>F12</kbd></span></label></li></ul><h3 id="_3-quel-outil-repond-a-quelle-question" tabindex="-1">3. Quel outil répond à quelle question ? <a class="header-anchor" href="#_3-quel-outil-repond-a-quelle-question" aria-label="Permalink to &quot;3. Quel outil répond à quelle question ?&quot;">​</a></h3><div class="outils-grille"><a class="outil" href="#partie-2"><strong>Wappalyzer</strong><span class="outil-question">Avec quoi le site est-il construit ?</span><span class="outil-partie">Partie 2 →</span></a><a class="outil" href="#partie-3"><strong>ICANN Lookup</strong><span class="outil-question">Depuis quand existe le domaine ? Chez qui est-il loué ?</span><span class="outil-partie">Partie 3 →</span></a><a class="outil" href="#partie-3"><strong>Le cadenas</strong><span class="outil-question">Qui a émis le certificat ? Jusqu&#39;à quand est-il valide ?</span><span class="outil-partie">Partie 3 →</span></a><a class="outil" href="#partie-4"><strong>PageSpeed Insights</strong><span class="outil-question">Le site est-il rapide et accessible ?</span><span class="outil-partie">Partie 4 →</span></a><a class="outil" href="#partie-4"><strong>F12 — mode appareil</strong><span class="outil-question">S&#39;affiche-t-il bien sur un téléphone ?</span><span class="outil-partie">Partie 4 →</span></a><a class="outil" href="#partie-5"><strong>Ctrl + U — code source</strong><span class="outil-question">Les indices confirment-ils la plateforme ?</span><span class="outil-partie">Partie 5 →</span></a></div><hr><h2 id="partie-1" tabindex="-1">Partie 1 — Première impression (10 min) <a class="header-anchor" href="#partie-1" aria-label="Permalink to &quot;Partie 1 — Première impression (10 min) {#partie-1}&quot;">​</a></h2><p>Parcourez les deux sites <strong>sans outil</strong>, comme un client ordinaire.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">À qui s&#39;adresse le site ? Qu&#39;est-ce qu&#39;on peut y faire (consulter le menu, réserver, commander, acheter, créer un compte…) ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Quels liens mènent vers un autre site (réservation, livraison, paiement, réseaux sociaux) ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Votre impression générale en trois mots</span></label></li></ul><hr><h2 id="partie-2" tabindex="-1">Partie 2 — Les technologies (15 min) <a class="header-anchor" href="#partie-2" aria-label="Permalink to &quot;Partie 2 — Les technologies (15 min) {#partie-2}&quot;">​</a></h2><p>Sur la page d&#39;accueil de chaque site, cliquez sur l&#39;icône <strong>Wappalyzer</strong>.</p>',20)),a(l,{mode:"extension"}),e[2]||(e[2]=t('<ul class="checklist"><li><label><input type="checkbox"><span class="check-text">La plateforme ou le CMS (WordPress, Shopify, Squarespace, Next.js…)</span></label></li><li><label><input type="checkbox"><span class="check-text">L&#39;hébergement et le serveur Web</span></label></li><li><label><input type="checkbox"><span class="check-text">Les services externes : réservation, paiement, commerce en ligne</span></label></li><li><label><input type="checkbox"><span class="check-text">Les outils d&#39;analyse et de publicité (Google Analytics, Meta Pixel…)</span></label></li><li><label><input type="checkbox"><span class="check-text">Les bibliothèques JavaScript et leurs versions (p. ex. jQuery)</span></label></li></ul><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Wappalyzer peut se tromper</strong><br> Il devine les technologies à partir d&#39;indices. Il en rate parfois, ou en voit qui n&#39;y sont pas. Si un résultat vous surprend, cherchez une preuve dans le code source (partie 5). </div><hr><h2 id="partie-3" tabindex="-1">Partie 3 — Domaine et sécurité (15 min) <a class="header-anchor" href="#partie-3" aria-label="Permalink to &quot;Partie 3 — Domaine et sécurité (15 min) {#partie-3}&quot;">​</a></h2><h3 id="le-nom-de-domaine" tabindex="-1">Le nom de domaine <a class="header-anchor" href="#le-nom-de-domaine" aria-label="Permalink to &quot;Le nom de domaine&quot;">​</a></h3><p>Dans <strong>ICANN Lookup</strong>, entrez le nom de domaine (sans <code>https://</code> ni <code>www</code>).</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">La date de création du domaine (depuis combien d&#39;années existe-t-il ?)</span></label></li><li><label><input type="checkbox"><span class="check-text">Le registraire (chez qui le domaine est loué)</span></label></li><li><label><input type="checkbox"><span class="check-text">La date d&#39;expiration</span></label></li></ul><h3 id="le-certificat" tabindex="-1">Le certificat <a class="header-anchor" href="#le-certificat" aria-label="Permalink to &quot;Le certificat&quot;">​</a></h3><p>Cliquez sur l&#39;icône à gauche de l&#39;adresse, puis sur <strong>La connexion est sécurisée → Le certificat est valide</strong> (les libellés varient selon le navigateur).</p>',9)),a(l,{mode:"cadenas"}),e[3]||(e[3]=t('<ul class="checklist"><li><label><input type="checkbox"><span class="check-text">L&#39;émetteur du certificat (Let&#39;s Encrypt, Google, Sectigo…)</span></label></li><li><label><input type="checkbox"><span class="check-text">Sa date d&#39;expiration</span></label></li></ul><h3 id="temoins-et-langue" tabindex="-1">Témoins et langue <a class="header-anchor" href="#temoins-et-langue" aria-label="Permalink to &quot;Témoins et langue&quot;">​</a></h3><p>Ouvrez le site dans une <strong>fenêtre de navigation privée</strong>.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Une bannière de témoins (cookies) apparaît-elle ? Permet-elle de <strong>refuser</strong> ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Dans quelle langue le site s&#39;affiche-t-il par défaut ?</span></label></li></ul><hr><h2 id="partie-4" tabindex="-1">Partie 4 — Performance et mobile (20 min) <a class="header-anchor" href="#partie-4" aria-label="Permalink to &quot;Partie 4 — Performance et mobile (20 min) {#partie-4}&quot;">​</a></h2><h3 id="pagespeed-insights" tabindex="-1">PageSpeed Insights <a class="header-anchor" href="#pagespeed-insights" aria-label="Permalink to &quot;PageSpeed Insights&quot;">​</a></h3><p>Analysez l&#39;<strong>adresse de la page d&#39;accueil</strong> de chaque site.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Onglet <strong>Mobile</strong> : score de performance, score d&#39;accessibilité, Largest Contentful Paint (LCP)</span></label></li><li><label><input type="checkbox"><span class="check-text">Onglet <strong>Ordinateur</strong> : score de performance</span></label></li><li><label><input type="checkbox"><span class="check-text">Dans les diagnostics : un problème principal qui ralentit le site</span></label></li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Les scores varient</strong><br> Deux analyses du même site peuvent donner des scores différents. Lancez l&#39;analyse <strong>deux fois</strong> et notez les deux résultats. </div><h4 id="situer-vos-resultats" tabindex="-1">Situer vos résultats <a class="header-anchor" href="#situer-vos-resultats" aria-label="Permalink to &quot;Situer vos résultats&quot;">​</a></h4>',11)),a(i),e[4]||(e[4]=t('<h3 id="l-affichage-sur-telephone" tabindex="-1">L&#39;affichage sur téléphone <a class="header-anchor" href="#l-affichage-sur-telephone" aria-label="Permalink to &quot;L&#39;affichage sur téléphone&quot;">​</a></h3><p>Dans le navigateur, ouvrez les outils de développement (<kbd>F12</kbd>), puis le <strong>mode appareil</strong> (<kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>M</kbd>). Choisissez un téléphone dans la liste. Si possible, ouvrez aussi le site sur <strong>votre vrai téléphone</strong>.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le texte est-il lisible sans zoomer ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Le menu est-il facile à ouvrir et à utiliser ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Les boutons importants (réserver, commander, appeler) sont-ils faciles à toucher ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Y a-t-il un défilement horizontal ou des éléments coupés ?</span></label></li></ul><hr><h2 id="partie-5" tabindex="-1">Partie 5 — Le code source (10 min) <a class="header-anchor" href="#partie-5" aria-label="Permalink to &quot;Partie 5 — Le code source (10 min) {#partie-5}&quot;">​</a></h2><p>Affichez le code source de la page d&#39;accueil (<kbd>Ctrl</kbd> + <kbd>U</kbd>), puis cherchez (<kbd>Ctrl</kbd> + <kbd>F</kbd>) :</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text"><code>&lt;title&gt;</code> : le titre est-il clair et descriptif ?</span></label></li><li><label><input type="checkbox"><span class="check-text"><code>description</code> : y a-t-il une description pour les moteurs de recherche ?</span></label></li><li><label><input type="checkbox"><span class="check-text"><code>lang=</code> : quelle langue est déclarée ?</span></label></li><li><label><input type="checkbox"><span class="check-text">Un indice qui confirme la plateforme trouvée par Wappalyzer (p. ex. <code>wp-content</code>, <code>myshopify.com</code>, <code>squarespace</code>, <code>_next</code>)</span></label></li></ul><hr><h2 id="partie-6" tabindex="-1">Partie 6 — Les contraintes probables (10 min) <a class="header-anchor" href="#partie-6" aria-label="Permalink to &quot;Partie 6 — Les contraintes probables (10 min) {#partie-6}&quot;">​</a></h2><p>Pour chaque site, imaginez une contrainte probable de chaque sorte. Appuyez-vous sur vos observations.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Sorte</th><th style="text-align:left;">Question</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Technique</strong></td><td style="text-align:left;">Qu&#39;est-ce que la technologie de ce site rendrait difficile ?</td></tr><tr><td style="text-align:left;"><strong>Organisationnelle</strong></td><td style="text-align:left;">Qui doit probablement mettre ce site à jour ? Est-ce simple pour cette personne ?</td></tr><tr><td style="text-align:left;"><strong>De ressources</strong></td><td style="text-align:left;">Qu&#39;est-ce que ce site coûte probablement à entretenir : argent, temps, compétences ?</td></tr></tbody></table><hr><h2 id="partie-7" tabindex="-1">Partie 7 — Le verdict (10 min) <a class="header-anchor" href="#partie-7" aria-label="Permalink to &quot;Partie 7 — Le verdict (10 min) {#partie-7}&quot;">​</a></h2><blockquote><p><strong>Lequel de ces deux sites serait le plus facile à faire évoluer ? Pourquoi ?</strong></p></blockquote><p>Par exemple : le restaurant veut ajouter la commande en ligne, traduire le site ou changer complètement son image.</p><p>Rédigez une justification de <strong>5 à 8 lignes</strong> qui s&#39;appuie sur <strong>au moins trois observations</strong> de votre fiche.</p><hr><h2 id="defi-bonus" tabindex="-1">Défi bonus <a class="header-anchor" href="#defi-bonus" aria-label="Permalink to &quot;Défi bonus&quot;">​</a></h2><p>Trouvez un site de restaurant québécois dont le <strong>score de performance mobile</strong> dans PageSpeed Insights est <strong>plus bas</strong> que ceux de votre paire. Notez l&#39;adresse, le score et <strong>deux causes</strong> probables de sa lenteur.</p><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">La fiche est complète pour les <strong>deux</strong> sites</span></label></li><li><label><input type="checkbox"><span class="check-text">Le verdict est justifié par au moins trois observations</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé <code>lab01-paireN-nom1-nom2.docx</code></span></label></li><li><label><input type="checkbox"><span class="check-text">La fiche est déposée dans l&#39;équipe Teams du cours</span></label></li></ul><hr><h2 id="mise-en-commun" tabindex="-1">Mise en commun <a class="header-anchor" href="#mise-en-commun" aria-label="Permalink to &quot;Mise en commun&quot;">​</a></h2><p>En grand groupe, chaque duo présente en une minute :</p><ul><li>la plateforme de chacun de ses deux sites ;</li><li>les scores de performance mobile ;</li><li>son verdict et <strong>la</strong> meilleure raison qui l&#39;appuie.</li></ul><p>On remplit ensemble un tableau des quatre paires pour comparer les approches.</p>',27))])}const k=n(u,[["render",p]]);export{f as __pageData,k as default};
